package com.bank.monitor;

import java.util.logging.Logger;

// Evaluates all three layers and produces an SLA verdict.
public class HealthMonitor {
    private static final Logger log = Logger.getLogger(HealthMonitor.class.getName());

    private final double slaTargetPercent;   // e.g. 99.95

    public HealthMonitor(double slaTargetPercent) {
        this.slaTargetPercent = slaTargetPercent;
    }

    public void evaluate(Ec2Metrics ec2, K8sWorkload k8s, JvmMetrics jvm) {
        // EC2 host layer
        if (!ec2.isStatusCheckOk())
            log.severe("EC2: status check FAILED — instance should be auto-recovered");
        if (ec2.getDiskPercent() > 90)
            log.severe(() -> "EC2: disk at " + ec2.getDiskPercent() + "% — risk of crash & log loss");
        if (ec2.getCpuPercent() > 85)
            log.warning(() -> "EC2: CPU at " + ec2.getCpuPercent() + "% — saturation risk");

        // Kubernetes workload layer
        if (k8s.getRestartsLast10m() >= 5)
            log.severe(() -> "K8s: " + k8s.getRestartsLast10m()
                    + " restarts/10m — crash loop (likely OOM-kill)");
        if (k8s.getPendingPods() > 0)
            log.warning(() -> "K8s: " + k8s.getPendingPods()
                    + " pending pod(s) — insufficient cluster capacity");

        // JVM layer
        if (jvm.getHeapUsedPercentAfterGc() > 85)
            log.severe(() -> "JVM: post-GC heap " + jvm.getHeapUsedPercentAfterGc()
                    + "% — memory leak heading for OutOfMemoryError");
        if (jvm.getGcPauseMsLastMinute() > 1000)
            log.warning(() -> "JVM: GC pauses " + jvm.getGcPauseMsLastMinute()
                    + "ms/min — latency spikes for transfers");

        // Availability from healthy replicas (redundancy keeps service up).
        double availability = 100.0 * k8s.getReadyReplicas() / k8s.getDesiredReplicas();
        // With 3 AZ replicas, 2/3 ready still serves traffic — service AVAILABLE.
        boolean serving = k8s.getReadyReplicas() >= 2;

        if (serving && availability >= slaTargetPercent) {
            log.info(() -> "SLA: healthy — " + k8s.getReadyReplicas() + "/"
                    + k8s.getDesiredReplicas() + " replicas ready, serving traffic");
        } else if (serving) {
            log.warning(() -> "SLA: DEGRADED — " + k8s.getReadyReplicas() + "/"
                    + k8s.getDesiredReplicas() + " ready; still serving but remediate fast");
        } else {
            log.severe("SLA: BREACH RISK — fewer than 2 replicas ready, failover/scale NOW");
        }
    }
}
