package com.bank.monitor;

import java.util.logging.*;

// Runnable demo: all three layers under stress; redundancy keeps the SLA.
public class HaMonitoringDemo {
    private static final Logger log = Logger.getLogger(HaMonitoringDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — HA health monitor (SLA target 99.95%)");

        HealthMonitor monitor = new HealthMonitor(99.95);

        // Host under disk pressure; one pod crash-looping on an OOM leak;
        // but 2 of 3 replicas still ready across AZs, so service stays available.
        Ec2Metrics ec2 = new Ec2Metrics(72.0, 68.0, 95.0, true);
        K8sWorkload k8s = new K8sWorkload(3, 2, 8, 0);
        JvmMetrics jvm = new JvmMetrics(88.0, 1400, 240);

        monitor.evaluate(ec2, k8s, jvm);

        log.info("Remediation: evict pod off the full-disk node, roll the leaking pod, "
               + "auto-scaling replaces the bad EC2 host; SLA protected by redundancy.");
    }
}
